  ('CSM:FILM 215', true, array['Cal-GETC Area 3A', 'AA/AS Degree Requirements: Area 3']::text[], array[]::text[], array[]::text[], array['FILM 100, FILM 121 or FILM 123 and ENGL C1000 (formerly ENGL 100) or ENGL C1000E (formerly ENGL 105)']::text[], 'verified', 'course_detail'),
