  ('CSM:FIRE 714', true, array[]::text[], array[]::text[], array[]::text[], array['Eligibility for ENGL C1000 (formerly ENGL 100) or ESL 400; FIRE 715']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 715', true, array[]::text[], array[]::text[], array[]::text[], array['Eligibility for ENGL C1000 (formerly ENGL 100) or ESL 400']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 717', true, array[]::text[], array[]::text[], array[]::text[], array['Eligibility for ENGL C1000 (formerly ENGL 100), ENGL C1000E (formerly ENGL 105), or ESL 400. Possession of a current Basic Life Support (BLS) certification from American Heart Association (AHA).']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 720', true, array[]::text[], array[]::text[], array[]::text[], array['Eligibility for ENGL C1000 (formerly ENGL 100) or ESL 400; FIRE 715']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 721', true, array[]::text[], array[]::text[], array[]::text[], array['Eligibility for ENGL C1000 (formerly ENGL 100) or ENGL C1000E (formerly ENGL 105) or ESL 400']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 722', true, array[]::text[], array['Proof of Emergency Medical Technician certification or Paramedic licensure. FIRE 715 or equivalent course from another accredited California Community College Fire Technology program and successful completion of at least three additional units of Fire Technology coursework or a minimum of one year of professional fire service experience in a suppression unit confirmed in writing by a supervising company officer or sponsorship by a fire service agency as a professional firefighter.']::text[], array[]::text[], array[]::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 725', true, array[]::text[], array[]::text[], array[]::text[], array['Eligibility for ENGL C1000 (formerly ENGL 100) or ESL 400; FIRE 715']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 730', true, array[]::text[], array[]::text[], array[]::text[], array['Eligibility for ENGL C1000 (formerly ENGL 100) or ESL 400; FIRE 715']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 740', true, array[]::text[], array[]::text[], array[]::text[], array['Eligibility for ENGL C1000 (formerly ENGL 100) or ESL 400; FIRE 715']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 745', true, array[]::text[], array[]::text[], array[]::text[], array['Eligibility for ENGL C1000 (formerly ENGL 100) or ESL 400; FIRE 715']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 748', true, array[]::text[], array[]::text[], array[]::text[], array['Eligibility for ENGL C1000 (formerly ENGL 100) or ESL 400; FIRE 715']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 770', true, array[]::text[], array[]::text[], array[]::text[], array['Eligibility for ENGL C1000 (formerly ENGL 100) or ESL 400; FIRE 715']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 787', true, array[]::text[], array['Possession of a valid, current EMT Basic Certificate, or expired no longer than two years.']::text[], array[]::text[], array['FIRE 797']::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 797', true, array[]::text[], array['Must be at least 18 years old prior to the end of the course., Current certification in Basic Life Support (BLS) for the healthcare provider/professional rescuer through the American Heart Association. Admission into the Emergency Medical Technician (EMT) course.']::text[], array['Vaccinations for healthcare workers per California Code of Regulations, Title 8, Section 5199 Aerosol Transmissible Diseases; Appendix E. Plus, additional vaccinations as listed on the Vaccination Recommendations for Healthcare Workers list, which can be found at http://collegeofsanmateo.edu/emt.']::text[], array[]::text[], 'verified', 'course_detail'),
  ('CSM:FIRE 798', true, array[]::text[], array[]::text[], array[]::text[], array[]::text[], 'unavailable', 'number_heuristic'),
  ('CSM:FIRE 810', false, array[]::text[], array['Successful completion of, or concurrent enrollment in, a State Fire Marshal certified basic firefighting academy or equivalent as determined by the Coordinator of the Fire Technology program. NOTE: Approval of equivalent training is not a guarantee state regulatory or licensing agencies will also grant equivalency. Successful completion of a National Registry certified Emergency Medical Technician: Basic course or equivalent as determined by the Coordinator of the Fire Technology program. NOTE: Approval of equivalent training is not a guarantee state regulatory or licensing agencies will also grant equivalency. Acceptance into a fire agency cadet program. Cadets (or volunteer firefighters) are subjected to an interview process by a fire department before being chosen as a cadet. Minimum requirements to be chosen as a cadet are successful completion of, or concurrent enrollment in, a Fire Academy, successful completion of an EMT course and possession of an EMT certificate, age of 18 or older, and a valid California Driver License.']::text[], array[]::text[], array[]::text[], 'partial', 'number_heuristic'),
  ('CSM:FIRE 811', false, array[]::text[], array['FIRE 810, Acceptance into a fire agency cadet program. Cadets (or volunteer firefighters) are subjected to an interview process by a fire department before being chosen as a cadet . Minimum requirements to be chosen as a cadet are successful completion of, or concurrent enrollment in, a Fire Academy, successful completion of an EMT course and possession of an EMT certificate, age of 18 or older, and a valid California Driver License.']::text[], array[]::text[], array[]::text[], 'partial', 'number_heuristic'),
  ('CSM:FIRE 812', false, array[]::text[], array['FIRE 811, Acceptance into a fire agency cadet program. Cadets (or volunteer firefighters) are subjected to an interview process by a fire department before being chosen as a cadet. Minimum requirements to be chosen as a cadet are successful completion of, or concurrent enrollment in, a Fire Academy, successful completion of an EMT course and possession of an EMT certificate, age of 18 or older, and a valid California Driver License.']::text[], array[]::text[], array[]::text[], 'partial', 'number_heuristic'),
